/** Renders the storybook map icons as reusable <symbol> defs (drop inside an SVG <defs>). */
export function MapIconSymbols(): JSX.Element {
  return (
    <>
      {Object.entries(STORYBOOK_MAP_ICONS).map(([key, inner]) => (
        <symbol key={key} id={`sbm-${key}`} viewBox="0 0 100 100">
          <g dangerouslySetInnerHTML={{ __html: inner }} />
        </symbol>
      ))}
    </>
  )
}
